\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs24  \plain \f1\fs24 6. (f. 201Ar, 8. Z. v. u.-201Av) Synodus Hierosolymitana contra concilium Florentinum (Ms. ohne Titel, direkt an das Vorangehende anschlie\u223 \'dfend), PG 147, 534, 11-32; edd. \plain \f2\scaps\lang1033\fs24 G. Hofmann - T. O' Shaughnessy - I. Simon\plain \f1\fs24 , Orientalium documenta minora (Concilium Florentinum, ser. A, Vol. III/3), Rom 1953, S. 68-72 (Nr. 45);\plain \f2\scaps\lang1033\fs24 V. Grumel - J. Darrouz\plain \f2\scaps\lang1033\fs24 \u232 \'e8\plain \f2\scaps\lang1033\fs24 s\plain \f1\fs24 , Les regestes des actes du patriarcat de Constantinople, vol. I: Les actes des patriarches, Fasc. VII: Les regestes de 1410 \u224 \'e0 1453, Paris 1991, Reg. 3391; \plain \f2\i\lang1033\fs24 inc. mut. \plain \f2\scaps\lang1033\fs24 Hofmann et al.\plain \f1\fs24 , S. 72, 1: \plain \f3\lang1032\fs24 \u964 \'f4\u959 \'ef\u8059 ?\u964 \'f4\u959 \'ef\u965 \'f5\u962 \'f2 \u948 \'e4\u949 \'e5\u967 \'f7\u8057 ?\u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u953 \'e9 \u954 \'ea\u945 \'e1\u8054 ? \u963 \'f3\u965 \'f5\u957 \'ed\u945 \'e1\u953 \'e9\u957 \'ed\u959 \'ef\u8166 ?\u957 \'ed\u964 \'f4\u945 \'e1\u962 \'f2 \u7952 ?\u957 \'ed \u964 \'f4\u959 \'ef\u8150 ?\u962 \'f2 \u964 \'f4\u959 \'ef\u953 \'e9\u959 \'ef\u8059 ? \u964 \'f4\u959 \'ef\u953 \'e9\u962 \'f2 \plain \f2\i\lang1033\fs24 des\plain \f1\fs24 . \plain \f3\lang1032\fs24 \u8003 ?\u957 \'ed \u954 \'ea\u945 \'e1\u8054 ? \u8000 ?\u966 \'f6\u949 \'e5\u8055 ?\u955 \'eb\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1 \u964 \'f4\u959 \'ef\u8166 ?\u964 \'f4\u959 \'ef\u957 \'ed \u964 \'f4\u951 \'e7\u961 \'f1\u8134 ?\u963 \'f3\u945 \'e1\u953 \'e9 \u7936 ?\u948 \'e4\u969 \'f9\u961 \'f1\u959 \'ef\u948 \'e4\u959 \'ef\u954 \'ea\u8053 ?\u964 \'f4\u969 \'f9\u962 \'f2 \u964 \'f4\u949 \'e5 \u954 \'ea\u945 \'e1\u8054 ? \u8000 ?\u961 \'f1\u952 \'e8\u8182 ?\u962 \'f2 \u964 \'f4\u8052 ?\u957 \'ed \u949 \'e5\u8016 ?\u963 \'f3\u8051 ?\u946 \'e2\u949 \'e5\u953 \'e9\u945 \'e1\u957 \'ed\plain \f4\lang1033\fs24 . \plain \f3\lang1032\fs24 \u959 \'ef\u8023 ? \u7957 ?\u957 \'ed\u949 \'e5\u954 \'ea\u949 \'e5\u957 \'ed \u7952 ?\u960 \'f0\u949 \'e5\u948 \'e4\u8057 ?\u952 \'e8\u951 \'e7 \u945 \'e1\u8016 ?\u964 \'f4\u8183 ?\plain \f4\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ? \plain \f4\lang1033\fs24 \u7969 ? \plain \f3\lang1032\fs24 \u7956 ?\u947 \'e3\u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u959 \'ef\u962 \'f2 \u7969 ?\u956 \'ec\u8182 ?\u957 \'ed \u947 \'e3\u961 \'f1\u8061 ?\u956 \'ec\u951 \'e7 \u963 \'f3\u965 \'f5\u957 \'ed\u959 \'ef\u948 \'e4\u953 \'e9\u954 \'ea\u8182 ?\u962 \'f2 \u7936 ?\u960 \'f0\u959 \'ef\u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u8050 ?\u957 \'ed \u7984 ?\u948 \'e4\u953 \'e9\u959 \'ef\u967 \'f7\u949 \'e5\u8055 ?\u961 \'f1\u969 \'f9\u962 \'f2 \u7952 ?\u957 \'ed\u956 \'ec\u951 \'e7\plain \f4\lang1033\fs24 (\plain \f3\lang1032\fs24 \u957 \'ed\u8054 ?\plain \f4\lang1033\fs24 ) \plain \f3\lang1032\fs24 \u7936 ?\u960 \'f0\u961 \'f1\u953 \'e9\u955 \'eb\u955 \'eb\u8055 ?\u8179 ? \u964 \'f4\u959 \'ef\u8166 ?\plain \f4\lang1033\fs24  \u987 ?\plain \f3\lang1032\fs24 \u959 \'ef\u8166 ?\plain \f4\lang1033\fs24  \u993 ?\plain \f3\lang1032\fs24 \u959 \'ef\u8166 ?\plain \f4\lang1033\fs24  \plain \f3\lang1032\fs24 \u957 \'ed\u959 \'ef\u8166 ?\plain \f4\lang1033\fs24  \plain \f3\lang1032\fs24 \u945 \'e1\u959 \'ef\u8166 ?\plain \f4\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2 \u957 \'ed\u8166 ?\u957 \'ed \u964 \'f4\u961 \'f1\u949 \'e5\u967 \'f7\u959 \'ef\u8059 ?\u963 \'f3\plain \f4\lang1033\fs24 (\plain \f3\lang1032\fs24 \u951 \'e7\u962 \'f2\plain \f4\lang1033\fs24 ) \plain \f3\lang1032\fs24 \u7984 ?\u957 \'ed\plain \f4\lang1033\fs24 (\plain \f3\lang1032\fs24 \u948 \'e4\u953 \'e9\u954 \'ea\u964 \'f4\u953 \'e9\u8182 ?\u957 \'ed\plain \f4\lang1033\fs24 )\plain \f3\lang1032\fs24 \u959 \'ef\u962 \'f2\plain \f4\lang1033\fs24 \u987 ?\plain \f3\lang1032\fs24 \u951 \'e7\u962 \'f2\plain \f4\lang1033\fs24 . \plain